// 切换到map034海边小树林

	If ($Event == 260) @Event260;
	
	FadeOut();
	SaveNpc();
	ClearBody();
	SaveObj();
	LoadMap("map034_海边小树林.map");
	LoadObj("map034.obj");
	LoadNpc("map034.npc");
	SetPlayerPos(11, 39);
	SetPlayerDir(0);
	ClearEffect();
	FadeIn();
	Return;


@Event260:
	FadeOut();
	SaveNpc();
	ClearBody();
	SaveObj();
	StopMusic();
	PlayMusic("萧鼓.mp3");
	LoadMap("map034_海边小树林.map");
	LoadObj("map034_event260.obj");
	LoadNpc("map034_event260.npc");
	SetPlayerPos(11, 39);
	SetPlayerDir(0);
	SetNpcScript("张琳心", "张琳心对话.txt");
	ClearEffect();
	FadeIn();
